// Builds one Slack message in the shared anatomy (EXPERIENCE.md): header,
// what happened, what to do, links. The plain `text` is the notification
// fallback: header plus what to do.

// Notice-kind words, copied from contracts/vocabulary.json (notice_kind).
// scripts/tests/test_n8n_workflows.py checks that this copy still matches.
const NOTICE_KIND = { info: 'FYI', action: 'Action needed', alert: 'Alert' };

const m = $('Message').first().json;
const channel = $('Settings').first().json.slack_channel ?? '';
const links = (Array.isArray(m.links) ? m.links : []).filter((l) => l && l.url && l.label);

const prefix = NOTICE_KIND[m.kind];
const header = prefix ? `${prefix}: ${m.header}` : String(m.header ?? '');
const todo = m.todo ? `What to do: ${m.todo}` : '';

const blocks = [{ type: 'header', text: { type: 'plain_text', text: header.slice(0, 150) } }];
if (m.body) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: m.body } });
if (todo) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*What to do:* ${m.todo}` } });
if (links.length) {
  blocks.push({
    type: 'context',
    elements: [{ type: 'mrkdwn', text: links.map((l) => `<${l.url}|${l.label}>`).join(' · ') }],
  });
}

const text = todo ? `${header.replace(/\.$/, '')}. ${todo}` : header;
const preview = [header, m.body, todo, links.map((l) => `${l.label}: ${l.url}`).join(' · ')]
  .filter(Boolean)
  .join('\n');

return [{ json: { channel, text, blocks, thread_ts: m.thread_ts || '', preview } }];

// Slack answers 200 even when it refuses a message, with ok: false.
const r = $input.first().json;
return [{ json: r.ok ? { posted: true, channel: r.channel, ts: r.ts } : { posted: false, error: `Slack said ${r.error}` } }];

// Slack could not be reached. Report a short reason; the caller decides what to do.
const e = $input.first().json.error;
const reason = String(e?.message ?? e ?? 'request failed').split('\n')[0].slice(0, 160);
return [{ json: { posted: false, error: `Slack unreachable: ${reason}` } }];

// Slack is not set up yet (no channel in Settings): nothing is sent. The
// message is returned as a preview, visible in this execution in n8n.
const m = $input.first().json;
return [{ json: { posted: false, preview: true, message: m.preview } }];
